// The site that ships (Nov 2026): site/, generated by redesign-2026-11/realis-lab/make_release.py
// and copied to dist/ by `npm run build`. It replaces the Astro pages' build tests (dist.test.mjs),
// keeping their rules that still hold: the form posts to this origin with a honeypot, the anonymised
// portal case never names its client, no surname, a security policy with no inline script.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync, existsSync, readdirSync, statSync } from 'node:fs';
import { join, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';
import { config } from '../src/config.ts';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', 'dist');
const read = (p) => readFileSync(join(ROOT, p), 'utf8');
const pages = [];
(function walk(d) { for (const f of readdirSync(d)) { const p = join(d, f); if (statSync(p).isDirectory()) walk(p); else if (f === 'index.html') pages.push(relative(ROOT, p)); } })(ROOT);
const langOf = (p) => (p.startsWith('fr/') ? 'fr' : p.startsWith('nl/') ? 'nl' : 'en');
const ROUTES = {
  home: ['', 'fr/', 'nl/'], services: ['services/', 'fr/services/', 'nl/diensten/'], projects: ['projects/', 'fr/projets/', 'nl/projecten/'],
  prices: ['prices/', 'fr/tarifs/', 'nl/prijzen/'], contact: ['contact/', 'fr/contact/', 'nl/contact/'],
  legal: ['legal/', 'fr/mentions-legales/', 'nl/wettelijke-vermeldingen/'], privacy: ['privacy/', 'fr/confidentialite/', 'nl/privacy/'],
  thanks: ['thanks/', 'fr/merci/', 'nl/bedankt/'],
};
for (const s of ['axel-de-lange', 'rodolphe-alexis-van-impe', 'recall', 'headquarters', 'approval-portal', 'vidimus']) ROUTES['p:' + s] = [`projects/${s}/`, `fr/projets/${s}/`, `nl/projecten/${s}/`];
// one page per service, under the Services addresses (15 Nov)
Object.assign(ROUTES, {
  'svc:websites': ['services/websites/', 'fr/services/sites-web/', 'nl/diensten/websites/'],
  'svc:client-portals': ['services/client-portals/', 'fr/services/portails-clients/', 'nl/diensten/klantenportalen/'],
  'svc:document-workflows': ['services/document-workflows/', 'fr/services/flux-documentaires/', 'nl/diensten/documentstromen/'],
  'svc:internal-tools': ['services/internal-tools/', 'fr/services/outils-internes/', 'nl/diensten/interne-tools/'],
});

test('every page exists in English, French and Dutch, at the live addresses', () => {
  for (const [key, routes] of Object.entries(ROUTES)) for (const r of routes) assert.ok(existsSync(join(ROOT, r, 'index.html')), `${key}: ${r} missing`);
  assert.equal(pages.length, Object.keys(ROUTES).length * 3);
});

test('each page carries its language, its canonical address and its three translations', () => {
  for (const p of pages) {
    const html = read(p), lang = langOf(p);
    assert.match(html, new RegExp(`<html lang="${lang}">`), p);
    assert.match(html, /<span class="lang" role="group"/, `${p}: no language switch`);
    if (/^(thanks|fr\/merci|nl\/bedankt)\//.test(p)) { assert.match(html, /<meta name="robots" content="noindex">/, p); continue; }
    const route = dirname(p) === '.' ? '' : dirname(p) + '/';
    assert.match(html, new RegExp(`<link rel="canonical" href="https://realisstudio.com/${route}">`), p);
    for (const l of ['en', 'fr', 'nl', 'x-default']) assert.match(html, new RegExp(`hreflang="${l}" href="https://realisstudio.com/`), `${p}: hreflang ${l}`);
    assert.match(html, /<meta name="description" content="[^"]{40,}">/, `${p}: description`);
  }
});

test('every link and file inside the site resolves', () => {
  for (const p of pages) {
    for (const m of read(p).matchAll(/(?:href|src|poster)="([^"#?]+)[^"]*"/g)) {
      const u = m[1];
      if (/^(https?:|mailto:|tel:|data:)/.test(u) || u.startsWith('/api/')) continue;
      let t = join(ROOT, dirname(p), u); if (u.endsWith('/') || u === './' || u === '..') t = join(t, 'index.html');
      assert.ok(existsSync(t), `${p} → ${u}`);
    }
  }
});

test('the lab never ships: no version bar, no grid overlay, no link into /lab/', () => {
  for (const p of pages) { const html = read(p); assert.doesNotMatch(html, /class="labbar"|class="grid-ov"|lab\/v\d/, p); }
});

test('the contact form posts to this origin, with honeypot, thank-you page and Turnstile', () => {
  for (const r of ROUTES.contact) {
    const html = read(join(r, 'index.html')), lang = langOf(r);
    assert.match(html, /<form class="cf-form" action="\/api\/contact" method="post"/);
    assert.match(html, /name="_honey"/);
    assert.match(html, new RegExp(`name="_next" value="https://realisstudio.com/${ROUTES.thanks[['en', 'fr', 'nl'].indexOf(lang)]}"`));
    assert.match(html, new RegExp(`data-sitekey="${config.turnstileSiteKey}"`));
    assert.match(html, /name="message"/);
  }
});

test('Prices is the in-place version, and software starts at 10,000 in every language', () => {
  for (const [r, amt] of [['prices/', 'from €10,000'], ['fr/tarifs/', 'à partir de 10 000 €'], ['nl/prijzen/', 'vanaf € 10.000']]) {
    const html = read(join(r, 'index.html'));
    assert.match(html, /<div class="pc-cards" data-mode="inline">/, r);
    assert.ok(html.includes(amt), `${r}: ${amt}`);
  }
  for (const p of pages) {
    const html = read(p).replace(/<fieldset class="cf-chips"><legend>[^<]*<\/legend>.*?<\/fieldset>/gs, '')  // the budget ranges are not a price
      .replace(/<span class="cf-slide-opts"[^>]*>.*?<\/span><\/span>/gs, '');  // nor are they as the slider's stops (19 Nov)
    assert.doesNotMatch(html, /€15,000|15 000 €|€ 15\.000/, p);
  }
});

test('Tbilisi is the financial office, never a head office', () => {
  for (const r of ROUTES.home) {
    const html = read(join(r, 'index.html'));
    assert.match(html, /Financial office|Bureau financier|Financieel kantoor/, r);
    assert.doesNotMatch(html, /[Hh]ead office|[Ss]iège|[Hh]oofdkantoor/, r);
  }
});

test('the anonymised portal case never names its client', () => {
  for (const r of ROUTES['p:approval-portal']) assert.doesNotMatch(read(join(r, 'index.html')).replace(/<a class="mw-card".*?<\/a>/gs, ''), /De Lange|docteurdelange/i, r);
});

test('every service page answers its questions as FAQPage data, in its own language', () => {
  for (const [key, routes] of Object.entries(ROUTES)) {
    if (!key.startsWith('svc:')) continue;
    for (const r of routes) {
      const html = read(join(r, 'index.html'));
      const m = html.match(/<script type="application\/ld\+json">(.*?)<\/script>/s);
      assert.ok(m, `${r}: no FAQ data`);
      const d = JSON.parse(m[1].replace(/<\\\//g, '</'));
      assert.equal(d['@type'], 'FAQPage', r);
      const shown = [...html.matchAll(/<summary>(.*?)<i/g)].map((x) => x[1].replace(/&amp;/g, '&').trim());
      assert.deepEqual(d.mainEntity.map((q) => q.name), shown, `${r}: data and page differ`);
    }
  }
});

// SEO mission R (NIRMATA, 20 Nov 2026): structured data, alt text, sitemap dates, fonts off the first paint
const graphOf = (html) => {
  const m = html.match(/<script type="application\/ld\+json" id="ld-site">(.*?)<\/script>/s);
  return m && JSON.parse(m[1].replace(/<\\\//g, '</'))['@graph'];
};
test('every indexable page describes itself as structured data, with only what the site states', () => {
  for (const [key, routes] of Object.entries(ROUTES)) {
    for (const r of routes) {
      const html = read(join(r, 'index.html')), g = graphOf(html);
      if (key === 'thanks') { assert.equal(g, null, r); continue; }
      assert.ok(g, `${r}: no structured data`);
      const types = g.map((n) => n['@type']);
      for (const t of ['Organization', 'WebSite']) assert.ok(types.includes(t), `${r}: no ${t}`);
      const page = g.find((n) => n['@id'] === `https://realisstudio.com/${r}#webpage`);
      assert.ok(page, `${r}: no node for the page itself`);
      assert.equal(page.inLanguage, langOf(r), r);
      if (key !== 'home') {
        const crumbs = g.find((n) => n['@type'] === 'BreadcrumbList').itemListElement;
        assert.equal(crumbs.at(-1).item, `https://realisstudio.com/${r}`, `${r}: breadcrumb ends elsewhere`);
      }
      if (key.startsWith('svc:')) assert.ok(types.includes('Service'), `${r}: no Service`);
      if (key.startsWith('p:')) assert.ok(types.includes('CreativeWork'), `${r}: no CreativeWork`);
      const org = g.find((n) => n['@type'] === 'Organization');
      assert.ok(!org.address && !types.includes('LocalBusiness'), `${r}: an address or LocalBusiness crept in`);
    }
  }
});

test('screenshots and card thumbnails have alt text; only grounds and tile layers stay empty', () => {
  for (const p of pages) {
    for (const m of read(p).matchAll(/<img\b[^>]*>/g)) {
      const t = m[0];
      if (!/\salt=""/.test(t)) continue;
      const src = (t.match(/\ssrc="([^"]+)"/) || [])[1] || '';
      const name = src.split('/').pop().split('?')[0];
      assert.match(name, /^(dl-theatre|rav-room|[a-z0-9]+-hbg|dl-ig-avatar|rv-|rc-)/, `${p}: ${name} has no alt`);
    }
  }
});

test('the sitemap gives every address the day it last changed', () => {
  const sm = read('sitemap-0.xml');
  const urls = [...sm.matchAll(/<url>(.*?)<\/url>/gs)].map((m) => m[1]);
  assert.ok(urls.length > 0);
  for (const u of urls) assert.match(u, /<\/loc><lastmod>\d{4}-\d{2}-\d{2}<\/lastmod>/, u.slice(0, 80));
});

test('the web fonts never hold the first paint', () => {
  for (const p of pages) {
    const html = read(p);
    assert.doesNotMatch(html, /<link rel="stylesheet" href="https:\/\/fonts\.googleapis\.com\/[^"]*">(?!<\/noscript>)/, p);
    if (html.includes('data-async')) assert.match(html, /<script async src="(\.\.\/)*css\.js\?v=[0-9a-f]{8}"><\/script>/, p);
  }
});

// Andy's surname appears only in the credit he asked for, on every project page (20 Nov: « I need to be listed under every
// project as lead software engineer », « I need to be mentioned Andy [Huizenga] as a lead engineer »), and nowhere else.
test('the surname appears only in the lead engineer credit, which every project page carries', () => {
  for (const p of pages) {
    const html = read(p);
    assert.doesNotMatch(html.replace(/<dd>Andy Huizenga<\/dd>/g, '').replace(/"name": "Andy Huizenga"/g, ''), /Huizenga/i, p);
    if (/^(projects|fr\/projets|nl\/projecten)\/[^/]+\/index\.html$/.test(p)) assert.match(html, /<dd>Andy Huizenga<\/dd>/, `${p}: no credit`);
  }
});

test('the headers carry a security policy with no inline script, and search engines are welcome', () => {
  const h = read('_headers');
  const script = h.match(/script-src([^;]*)/)[1];
  assert.doesNotMatch(script, /'unsafe-inline'/);
  assert.match(script, /static\.cloudflareinsights\.com/);
  assert.match(h, /frame-ancestors 'none'/);
  assert.doesNotMatch(h, /noindex/i);
  assert.match(read('robots.txt'), /Allow: \//);
  const locs = [...read('sitemap-0.xml').matchAll(/<loc>/g)].length;
  assert.equal(locs, (Object.keys(ROUTES).length - 1) * 3);
});
